/// Whether a failure is bad command-line input (exit 2) or anything else (exit 1).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ExitKind {
    /// A bad or missing flag or argument value, or a bad flag combination, caught after parsing.
    Usage,
    /// Workspace, config, git, registry or release state.
    Runtime,
}

impl GraphError {
    pub fn exit_kind(&self) -> ExitKind {
        match self {
            Self::Config(error) => error.exit_kind(),
            Self::InitInvalidForgeRepository { .. }
            | Self::InitInvalidTargetTriple { .. }
            | Self::TagInvalid { .. } => ExitKind::Usage,
            _ => ExitKind::Runtime,
        }
    }

    /// E102 for `id`, suggesting up to three of `known` whose names are a small edit away.
    pub fn unknown_package(id: PackageId, known: impl IntoIterator<Item = PackageId>) -> Self {
        let hint = did_you_mean(&id, known);
        Self::UnknownPackage { id, hint }
    }

    /// The one filesystem path this error is about, when it carries it as a structured field.
    pub fn path(&self) -> Option<&std::path::Path> {
        match self {
            Self::Config(error) => error.path(),
            Self::ParseChangeset { path, .. }
            | Self::UnexpectedManifestVersion { path, .. }
            | Self::PartialVersionRun { path, .. }
            | Self::ApplyIo { path, .. }
            | Self::UnsafeArtifactPath { path, .. }
            | Self::ArtifactRead { path, .. }
            | Self::ArtifactBytesMismatch { path }
            | Self::ArtifactAttestation { path, .. }
            | Self::ReleaseInputRead { path, .. }
            | Self::ReleaseDecisionDecode { path, .. }
            | Self::InitAlreadyInitialized { path }
            | Self::InitIo { path, .. }
            | Self::InitWorkflowExists { path } => Some(path),
            _ => None,
        }
    }
}

impl ConfigError {
    pub fn exit_kind(&self) -> ExitKind {
        match self {
            // The same reference read from callisto.toml is a config error, not usage.
            Self::ColonReference { context, .. } | Self::BareReference { context, .. } if context.starts_with("--") => {
                ExitKind::Usage
            }
            _ => ExitKind::Runtime,
        }
    }

    /// The one filesystem path this error is about, when it carries it as a structured field.
    pub fn path(&self) -> Option<&std::path::Path> {
        match self {
            Self::Read { path, .. }
            | Self::ParseToml { path, .. }
            | Self::UnknownField { path, .. }
            | Self::InvalidValue { path, .. }
            | Self::InvalidPublishTarget { path, .. }
            | Self::InvalidReleaseTrigger { path, .. }
            | Self::InvalidCascadeMode { path, .. }
            | Self::InvalidChangelogLayout { path, .. }
            | Self::InvalidRegistryKind { path, .. }
            | Self::RegistryPublishUrlNotPypi { path, .. }
            | Self::CargoRegistryUrl { path, .. }
            | Self::InvalidRegistryTimeout { path, .. }
            | Self::InvalidPackageMatch { path, .. } => Some(path),
            _ => None,
        }
    }

    /// Rejects a colon-qualified package reference (`cargo:foo`); the slash form (`cargo/foo`) is the only qualified spelling.
    pub fn reject_colon_form(raw: &str, context: &str) -> Result<(), Self> {
        match PackageId::colon_form_canonical(raw) {
            Some(canonical) => Err(Self::ColonReference {
                context: context.to_owned(),
                given: raw.to_owned(),
                canonical,
            }),
            None => Ok(()),
        }
    }

    /// Requires the canonical `eco/name` form: the colon form is E316 and a name without an ecosystem is E317.
    pub fn require_qualified(raw: &str, context: &str) -> Result<(), Self> {
/// guarantees a stable shape regardless of which [`CliError`] variant is
/// serialized.
pub fn format_error_json(command: &str, dry_run: bool, err: &CliError) -> serde_json::Value {
    let code = err.code().map(|c| c.to_string()).unwrap_or_else(|| "E000".to_string());
    let help = err.help().map(|h| h.to_string());
    let path = err.path().map(|p| p.display().to_string());
    serde_json::json!({
        "schemaVersion": callisto_model::SCHEMA_VERSION,
        "command": command,
        "dryRun": dry_run,
        "error": {
            "code": code,
            "message": err.to_string(),
            "help": help,
            "path": path,
        }
    })
}

impl CliError {
    pub fn exit_kind(&self) -> ExitKind {
        match self {
            Self::Graph(error) => error.exit_kind(),
            Self::Config(error) => error.exit_kind(),
            Self::NotATty
            | Self::ReleaseArtifactManifestDryRun
            | Self::ReleasePlanDryRun
            | Self::ReleaseExecuteDryRun
            | Self::ReleasePendingFromInvalid { .. }
            | Self::ReleaseBuildPythonDryRun
            | Self::ReleaseCommitInvalid { .. }
            | Self::ReleaseDecisionOutsideSource { .. }
            | Self::ReleaseDecisionPathInvalid { .. }
            | Self::ReleasePackageInvalid { .. }
            | Self::ReleaseOrchestrationRevisionInvalid { .. }
            | Self::ReleaseArtifactRepositoryInvalid { .. }
            | Self::ReleaseOrchestrationFlagsRequired
            | Self::InitRequiresYes { .. }
            | Self::InitMissingFlags { .. }
            | Self::InitWorkflowFlagsConflict
            | Self::InitFlagRequiresArtifactTarget { .. }
            | Self::AddInvalidPackageSpec { .. }
            | Self::InvalidSeverity { .. }
            | Self::AddSummaryRequired
            | Self::AddDuplicatePackage { .. }
            | Self::AddSummaryEmpty
            | Self::VersionEmitDryRun { .. }
            | Self::PreTagEmpty
            | Self::ReleasePrCommitPlanDryRun
            | Self::HelpUnknownCommand { .. } => ExitKind::Usage,
            _ => ExitKind::Runtime,
//! Usage errors exit 2 and runtime failures exit 1, for text and JSON output alike.
#[path = "common/release_harness.rs"]
mod release_harness;

use std::fs;
use std::process::Command;

use release_harness::*;

fn workspace() -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    fs::write(
        root.join("Cargo.toml"),
        "[package]\nname = \"a\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    fs::create_dir_all(root.join("src")).unwrap();
    fs::write(root.join("src/lib.rs"), "").unwrap();
    git(root, &["add", "."]);
    git(root, &["commit", "-m", "workspace"]);
    dir
}

fn assert_exit(dir: &std::path::Path, args: &[&str], exit: i32, code: &str) {
    let json = callisto(dir, args);
    assert_eq!(json.status.code(), Some(exit), "json {args:?}: {}", stderr_of(&json));
    // `init` prints what it detected before the envelope.
    let stderr = stderr_of(&json);
    let body = stderr.find("{\n").map_or(stderr.as_str(), |start| &stderr[start..]);
    let envelope: serde_json::Value = serde_json::from_str(body)
        .unwrap_or_else(|error| panic!("{args:?} stderr has no JSON envelope ({error}): {stderr}"));
    assert_eq!(envelope["error"]["code"], code, "{args:?}: {envelope}");

    let text = Command::new(env!("CARGO_BIN_EXE_callisto"))
        .args(["--cwd", dir.to_str().unwrap()])
        .args(args)
        .output()
        .unwrap();
    assert_eq!(text.status.code(), Some(exit), "text {args:?}: {}", stderr_of(&text));
}

#[test]
fn bad_or_missing_flag_values_checked_after_parsing_exit_2() {
    let dir = workspace();
    let root = dir.path();
    for (args, code) in [
        (vec!["add", "--package", "a:patch", "--summary", "s"], "E317"),
        (vec!["add", "--package", "cargo/a:bogus", "--summary", "s"], "E271"),
        (vec!["add", "--package", "cargo/a:patch"], "E274"),
        (vec!["add", "--package", "cargo/a:patch", "--summary", ""], "E275"),
        (vec!["add"], "E214"),
        (vec!["init"], "E240"),
        (vec!["init", "--workflow", "--no-workflow"], "E242"),
        (vec!["snapshot", "--tag", "a/b c"], "E324"),
        (vec!["pre", "enter", " "], "E279"),
    ] {
        assert_exit(root, &args, 2, code);
    }
}

#[test]
fn arguments_rejected_while_parsing_exit_2_and_help_and_version_exit_0() {
    let dir = workspace();
    let root = dir.path();
    for args in [
        vec!["status", "--no-such-flag"],
        vec!["no-such-command"],
        vec!["--format", "yaml", "status"],
        vec!["pre", "enter"],
        vec!["--no-such-flag"],
    ] {
        for format in ["json", "text"] {
            let out = Command::new(env!("CARGO_BIN_EXE_callisto"))
                .args(["--format", format, "--cwd", root.to_str().unwrap()])
                .args(&args)
                .output()
                .unwrap();
            assert_eq!(out.status.code(), Some(2), "{format} {args:?}: {}", stderr_of(&out));
        }
    }
    for args in [vec!["--help"], vec!["status", "--help"], vec!["--version"]] {
        let out = Command::new(env!("CARGO_BIN_EXE_callisto"))
            .args(&args)
            .output()
            .unwrap();
        assert_eq!(out.status.code(), Some(0), "{args:?}: {}", stderr_of(&out));
    }
}

#[test]
fn runtime_failures_still_exit_1() {
    let dir = workspace();
    let root = dir.path();
    assert_exit(
        root,
        &["add", "--package", "cargo/nope:patch", "--summary", "s"],
        1,
        "E102",
    );
    fs::write(root.join("callisto.toml"), "not = [valid").unwrap();
    assert_exit(root, &["status"], 1, "E111");
}

#[test]
fn a_bare_package_in_config_exits_1_though_the_same_code_on_a_flag_exits_2() {
    let dir = workspace();
    let root = dir.path();
    fs::write(root.join("callisto.toml"), "[[package]]\nmatch = \"a\"\n").unwrap();
    assert_exit(root, &["status"], 1, "E317");
}

